CREATE TABLE contact_tags(id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),name text NOT NULL CHECK(char_length(btrim(name)) BETWEEN 1 AND 80),color text CHECK(color IS NULL OR color ~ '^#[0-9A-Fa-f]{6}$'),created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,id),UNIQUE(workspace_id,name));
CREATE TABLE contact_tag_links(workspace_id uuid NOT NULL REFERENCES workspaces(id),contact_id uuid NOT NULL,tag_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,contact_id,tag_id),FOREIGN KEY(workspace_id,contact_id) REFERENCES contacts(workspace_id,id) ON DELETE CASCADE,FOREIGN KEY(workspace_id,tag_id) REFERENCES contact_tags(workspace_id,id) ON DELETE CASCADE);
ALTER TABLE contact_tags ENABLE ROW LEVEL SECURITY;ALTER TABLE contact_tags FORCE ROW LEVEL SECURITY;CREATE POLICY contact_tags_scope ON contact_tags USING(workspace_id=current_setting('app.workspace_id',true)::uuid) WITH CHECK(workspace_id=current_setting('app.workspace_id',true)::uuid);
ALTER TABLE contact_tag_links ENABLE ROW LEVEL SECURITY;ALTER TABLE contact_tag_links FORCE ROW LEVEL SECURITY;CREATE POLICY contact_tag_links_scope ON contact_tag_links USING(workspace_id=current_setting('app.workspace_id',true)::uuid) WITH CHECK(workspace_id=current_setting('app.workspace_id',true)::uuid);
GRANT SELECT,INSERT,UPDATE,DELETE ON contact_tags,contact_tag_links TO gotek_app;
